package com.campusconnect.assignment;
import com.campusconnect.course.*; import com.campusconnect.user.*; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.HttpStatus; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.security.Principal; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/assignments") public class AssignmentController {private final AssignmentRepository assignments;private final SubmissionRepository submissions;private final CourseRepository courses;private final UserRepository users;public AssignmentController(AssignmentRepository a,SubmissionRepository s,CourseRepository c,UserRepository u){assignments=a;submissions=s;courses=c;users=u;}
public record AssignmentRequest(@NotBlank @Size(max=180) String title,@Size(max=5000) String description,@NotNull Long courseId,@NotNull LocalDateTime dueAt){} public record SubmitRequest(@NotBlank @Size(max=10000) String content){} public record GradeRequest(@NotNull @DecimalMin("0.0") @DecimalMax("100.0") Double grade,@Size(max=2000) String feedback){}
@GetMapping public List<Map<String,Object>> list(@RequestParam(required=false) Long courseId){return (courseId==null?assignments.findAllByOrderByDueAtAsc():assignments.findByCourseIdOrderByDueAtAsc(courseId)).stream().map(this::dto).toList();}
@PostMapping @ResponseStatus(HttpStatus.CREATED) @PreAuthorize("hasAnyRole('FACULTY','ADMIN')") public Map<String,Object> create(@Valid @RequestBody AssignmentRequest r,Principal p){var c=courses.findById(r.courseId()).orElseThrow(()->new IllegalArgumentException("Course not found"));var u=users.findByEmailIgnoreCase(p.getName()).orElseThrow();return dto(assignments.save(new Assignment(r.title(),r.description(),c,u,r.dueAt())));}
@PutMapping("/{id}") @PreAuthorize("hasAnyRole('FACULTY','ADMIN')") public Map<String,Object> update(@PathVariable Long id,@Valid @RequestBody AssignmentRequest r){var a=assignments.findById(id).orElseThrow(()->new IllegalArgumentException("Assignment not found"));var c=courses.findById(r.courseId()).orElseThrow(()->new IllegalArgumentException("Course not found"));if(!a.getCourse().getId().equals(c.getId()))throw new IllegalArgumentException("Changing an assignment's course is not supported");a.update(r.title(),r.description(),r.dueAt());return dto(assignments.save(a));}
@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) @PreAuthorize("hasRole('ADMIN')") public void delete(@PathVariable Long id){assignments.delete(assignments.findById(id).orElseThrow(()->new IllegalArgumentException("Assignment not found")));}
@PostMapping("/{id}/submissions") @ResponseStatus(HttpStatus.CREATED) @PreAuthorize("hasRole('STUDENT')") public Map<String,Object> submit(@PathVariable Long id,@Valid @RequestBody SubmitRequest r,Principal p){var a=assignments.findById(id).orElseThrow(()->new IllegalArgumentException("Assignment not found"));var u=users.findByEmailIgnoreCase(p.getName()).orElseThrow();var existing=submissions.findByAssignmentIdAndStudentEmail(id,p.getName());var s=existing.orElseGet(()->new Submission(a,u,r.content()));if(existing.isPresent())s.updateContent(r.content());return submissionDto(submissions.save(s));}
@GetMapping("/submissions/mine") @PreAuthorize("hasRole('STUDENT')") public List<Map<String,Object>> mine(Principal p){return submissions.findByStudentEmailOrderBySubmittedAtDesc(p.getName()).stream().map(this::submissionDto).toList();}
@GetMapping("/{id}/submissions") @PreAuthorize("hasAnyRole('FACULTY','ADMIN')") public List<Map<String,Object>> forAssignment(@PathVariable Long id){return submissions.findByAssignmentIdOrderBySubmittedAtDesc(id).stream().map(this::submissionDto).toList();}
@PutMapping("/submissions/{submissionId}/grade") @PreAuthorize("hasAnyRole('FACULTY','ADMIN')") public Map<String,Object> grade(@PathVariable Long submissionId,@Valid @RequestBody GradeRequest r){var s=submissions.findById(submissionId).orElseThrow(()->new IllegalArgumentException("Submission not found"));s.grade(r.grade(),r.feedback());return submissionDto(submissions.save(s));}
private Map<String,Object> dto(Assignment a){return Map.of("id",a.getId(),"title",a.getTitle(),"description",a.getDescription()==null?"":a.getDescription(),"courseId",a.getCourse().getId(),"courseTitle",a.getCourse().getTitle(),"courseCode",a.getCourse().getCode(),"createdBy",a.getCreatedBy().getName(),"dueAt",a.getDueAt(),"createdAt",a.getCreatedAt());}
private Map<String,Object> submissionDto(Submission s){Map<String,Object> m=new LinkedHashMap<>();m.put("id",s.getId());m.put("assignmentId",s.getAssignment().getId());m.put("assignmentTitle",s.getAssignment().getTitle());m.put("studentName",s.getStudent().getName());m.put("studentEmail",s.getStudent().getEmail());m.put("content",s.getContent());m.put("submittedAt",s.getSubmittedAt());m.put("grade",s.getGrade());m.put("feedback",s.getFeedback());return m;}}
